//! 20-input smart-student export: load, cross-check against Python, and dispatch.
//! The fixture is generated by the AI exporter (see edge/BUILD_LOG.md) and is
//! read-only here.

use potok_edge::fixture::{build_fixture, FixtureConfig};
use potok_edge::frame::{RequestFrame, FLAG_IMU_OK, PHASE_LANDING, PROTOCOL_VERSION};
use potok_edge::model::Model;
use potok_edge::runtime::Runtime;
use potok_edge::student_runtime::{
    model_kind, smart_frame, StudentRuntime, COND_FEATURES, PHYSICS_FEATURES, SMART_FRAME_FEATURES,
};
use potok_edge::SpeculativeRuntime;
use std::fs;
use std::path::{Path, PathBuf};

const SEED: u64 = 0x504F544B;

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// Exactly the frame built by the read-only generator script: 14 physics
/// features then 6 conditioning numbers, values computed in f64 and cast once
/// to f32 as the Python `torch.as_tensor(..., dtype=float32)` does.
fn frame(n: usize) -> [f32; SMART_FRAME_FEATURES] {
    let n = n as f64;
    let c = |v: f64| v as f32;
    let mut physics = [0.0f32; PHYSICS_FEATURES];
    physics[..8].copy_from_slice(&[
        c(0.01 * n),
        c(-0.02 * n),
        0.03,
        0.05,
        9.81,
        -0.03,
        c((n * 0.1).sin() * 10.0),
        c(1000.0 + n),
    ]);
    physics[8..].copy_from_slice(&[
        c((n * 0.07).sin() * 5.0),
        c((n * 0.05).cos() * 3.0),
        c(0.5 + 0.01 * n),
        c(0.02 * n),
        c(0.8 + 0.001 * n),
        0.95,
    ]);
    smart_frame(&physics, &[13.0, 0.0082, 0.35, 0.95, 3000.0, 0.01])
}

#[test]
fn smart_fixture_has_the_documented_width() {
    let bytes = fs::read(fixture_dir().join("smart_student.bin")).unwrap();
    assert_eq!(model_kind(&bytes).unwrap(), 2);
    let model = potok_edge::StudentModel::from_bytes(&bytes).unwrap();
    assert_eq!(model.in_features, SMART_FRAME_FEATURES);
    assert_eq!(model.width, 64);
    assert_eq!((model.n_blocks, model.n_loops), (2, 2));
    assert_eq!(model.out_features, 2);
}

#[test]
fn rust_smart_inference_matches_python_within_1e_5() {
    let bin = fixture_dir().join("smart_student.bin");
    let expected = fs::read_to_string(fixture_dir().join("smart_student_expected.txt")).unwrap();
    let mut max_err = 0.0f32;
    let mut cases = 0usize;
    for line in expected.lines().filter(|l| !l.trim().is_empty()) {
        let parts: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(parts.len(), 4, "bad golden line: {line}");
        let warm = match parts[0] {
            "single" => 0usize,
            "warm3" => 3,
            "warm50" => 50,
            other => panic!("unknown case {other}"),
        };
        let reference: Vec<f32> = parts[1..].iter().map(|s| s.parse().unwrap()).collect();

        let mut student = StudentRuntime::from_file(&bin).unwrap();
        if warm > 0 {
            let window: Vec<f32> = (0..warm).flat_map(frame).collect();
            student.warmup(&window);
        }
        let out = student.step(&frame(warm));
        for k in 0..3 {
            let err = (out[k] - reference[k]).abs();
            max_err = max_err.max(err);
            assert!(
                err <= 1e-5,
                "{} out[{k}]: rust {} vs python {}, err {err:.3e}",
                parts[0],
                out[k],
                reference[k]
            );
        }
        cases += 1;
    }
    assert_eq!(cases, 3);
    println!("smart student: {cases} cases, max |rust - python| = {max_err:.3e}");
}

#[test]
fn dispatch_accepts_the_smart_student_and_conditioning() {
    let teacher =
        Runtime::new(Model::from_bytes(&build_fixture(FixtureConfig::default(), SEED)).unwrap());
    let student = StudentRuntime::from_file(fixture_dir().join("smart_student.bin")).unwrap();
    assert_eq!(student.model().in_features, SMART_FRAME_FEATURES);
    let mut rt = SpeculativeRuntime::new(teacher, student);
    rt.set_conditioning([13.0, 0.0082, 0.35, 0.95, 3000.0, 0.01]);
    for seq in 1..=40u16 {
        let req = RequestFrame {
            seq,
            time_us: seq as u32 * 20_000,
            phase: PHASE_LANDING,
            version: PROTOCOL_VERSION,
            flags: FLAG_IMU_OK,
            gyro: [0.02, -0.01, 0.005],
            accel: [0.05, 9.79, -0.03],
            mag: [1.0, 2.0, 3.0],
            height: 1500.0 + seq as f32,
            pitot_dp: (seq % 50) as i16,
        };
        let reply = rt.on_request(&req);
        assert_eq!(reply.seq, seq);
        assert!(rt.last_g.iter().all(|v| v.is_finite()));
        assert!(rt.student().state().iter().all(|v| v.is_finite()));
    }
    assert_eq!(rt.counters.frames, 40);
    assert_eq!(rt.counters.student_calls, 40);
    assert!(
        rt.counters.teacher_calls <= 40,
        "one teacher call per cycle"
    );
    assert_eq!(COND_FEATURES, 6);
}
